rng=np.random.default_rng(1)
A={'cos':lambda q: np.cos(q*t),'sin':lambda q: np.sin(q*t),'pow':lambda q: t**q,'expt':lambda q: np.exp(-q*t),'t2':None}
B={'1':lambda: np.ones_like(t),'x':lambda: x,'v':lambda: v,'xv':lambda: x*v,'x2':lambda: x**2,'v2':lambda: v**2,'sv':lambda: np.sqrt(v),'ix':lambda: 1/x,'Ev':lambda: np.exp(-np.sqrt(v))}
Tt={'1':lambda: np.ones_like(t),'x':lambda: x,'v':lambda: v,'xv':lambda: x*v,'t2':lambda: t**2,'t':lambda: t,'x2':lambda: x**2,'v2':lambda: v**2,'sv':lambda: np.sqrt(v),'ix':lambda: 1/x}
Ev=np.exp(-np.sqrt(v))
results=[]
for an,fa in A.items():
  for bn,fb in B.items():
    for cn,fc in Tt.items():
      if an=='t2': continue
      Bv=fb(); Cv=fc()
      def model(p):
          q=p[3]
          Av=fa(q) if an!='pow' else t**q
          return p[0]*Ev*0+p[0]*np.exp(-p[1]*np.sqrt(v))+p[2]*Av*Bv+p[4]*Cv
